def erreurs_par_groupe(predictions, verites, groupes):
    erreurs, tailles = {}, {}
    for p, v, g in zip(predictions, verites, groupes):
        erreurs[g] = erreurs.get(g, 0) + (p != v)
        tailles[g] = tailles.get(g, 0) + 1
    return {g: round(erreurs[g] / tailles[g], 2) for g in tailles}

