def exactitude_par_groupe(predictions, verites, groupes):
    resultat = {}
    for g in sorted(set(groupes)):
        paires = [(p, v) for p, v, x in zip(predictions, verites, groupes) if x == g]
        resultat[g] = round(sum(1 for p, v in paires if p == v) / len(paires), 2)
    return resultat


def audit(predictions, verites, groupes, tolerance):
    par_groupe = exactitude_par_groupe(predictions, verites, groupes)
    ecart = round(max(par_groupe.values()) - min(par_groupe.values()), 2)
    return {"par_groupe": par_groupe, "ecart": ecart, "alerte": ecart > tolerance}
